// Per-customer rate limit for proactive agent messages.
//
// Rule: no customer receives more than LIMIT proactive messages in any
// rolling WINDOW_MS period, counted across all channels together.
//
// State lives in STATE_DIR, one JSON file per customer, so that several
// worker processes on the same server share one count. Each customer has a
// lock directory; mkdir is atomic, so only one process at a time reads and
// updates a given customer's file. Different customers use different locks
// and never wait on each other.

import { createHash, randomUUID } from 'node:crypto';
import { mkdir, open, readFile, rename, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';

const LIMIT = 5;
const WINDOW_MS = 24 * 60 * 60 * 1000;
const CHANNELS = new Set(['sms', 'push', 'chat']);

// The lock is held for milliseconds. A lock older than LOCK_STALE_MS is
// assumed to belong to a process that crashed while holding it.
const LOCK_STALE_MS = 10_000;
const LOCK_TIMEOUT_MS = 15_000;

/**
 * Decide whether a proactive message to `userId` on `channel` may be sent now.
 *
 * If allowed, the send is counted immediately. If not allowed, nothing is
 * counted.
 *
 * @param {string} userId
 * @param {'sms' | 'push' | 'chat'} channel
 * @param {Date} now the current instant
 * @returns {Promise<{ allowed: boolean, retryAt: Date | null, reason: string }>}
 */
export async function reserve(userId, channel, now) {
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('userId must be a non-empty string');
  }
  if (!CHANNELS.has(channel)) {
    throw new TypeError(`channel must be one of sms, push, chat; got ${String(channel)}`);
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }

  const dir = process.env.STATE_DIR;
  if (!dir) {
    throw new Error('STATE_DIR environment variable is not set');
  }
  await mkdir(dir, { recursive: true });

  const key = createHash('sha256').update(userId).digest('hex');
  const dataFile = join(dir, `${key}.json`);
  const lockDir = join(dir, `${key}.lock`);
  const t = now.getTime();

  await acquireLock(lockDir);
  try {
    // Keep only sends that are still inside the window. A send at time s
    // counts for a check at time t while s > t - WINDOW_MS.
    const sent = (await readSent(dataFile))
      .filter((s) => s > t - WINDOW_MS)
      .sort((a, b) => a - b);

    if (sent.length < LIMIT) {
      sent.push(t);
      await writeSent(dataFile, sent);
      return {
        allowed: true,
        retryAt: null,
        reason: `Allowed: ${sent.length} of ${LIMIT} proactive messages used in the last 24 hours.`,
      };
    }

    // The next send becomes possible when enough old sends have left the
    // window. With LIMIT sends in the window, that is when the oldest one
    // expires.
    const expiring = sent[sent.length - LIMIT];
    const retryAt = new Date(expiring + WINDOW_MS);
    return {
      allowed: false,
      retryAt,
      reason: `Blocked: this customer already received ${LIMIT} proactive messages in the last 24 hours (the limit applies across sms, push and chat together). The next one can be sent after ${retryAt.toISOString()}.`,
    };
  } finally {
    await releaseLock(lockDir);
  }
}

async function acquireLock(lockDir) {
  const deadline = Date.now() + LOCK_TIMEOUT_MS;
  for (;;) {
    try {
      await mkdir(lockDir);
      return;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
    }

    try {
      const info = await stat(lockDir);
      if (Date.now() - info.mtimeMs > LOCK_STALE_MS) {
        await rm(lockDir, { recursive: true, force: true });
        continue;
      }
    } catch (err) {
      // The lock was released between our mkdir and stat. Try again.
      if (err.code === 'ENOENT') continue;
      throw err;
    }

    if (Date.now() > deadline) {
      throw new Error(`timed out waiting for lock ${lockDir}`);
    }
    await sleep(5 + Math.random() * 15);
  }
}

function releaseLock(lockDir) {
  return rm(lockDir, { recursive: true, force: true });
}

async function readSent(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }

  // A corrupt file fails closed: the call throws and nothing is sent.
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`rate-limit state file ${file} is not valid JSON: ${err.message}`);
  }
  if (!Array.isArray(data.sent) || !data.sent.every(Number.isFinite)) {
    throw new Error(`rate-limit state file ${file} has an unexpected shape`);
  }
  return data.sent;
}

async function writeSent(file, sent) {
  // Write to a temporary file and rename it, so a crash never leaves a
  // half-written state file behind.
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  const handle = await open(tmp, 'w');
  try {
    await handle.writeFile(JSON.stringify({ sent }));
    await handle.sync();
  } finally {
    await handle.close();
  }
  await rename(tmp, file);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, utimes, mkdir, writeFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g4-2/bot.mjs';
const { reserve } = await import(BOT);
const H = 60 * 60 * 1000;
const T0 = new Date('2026-10-23T10:00:00.000Z');

let dir;
beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bot-state-'));
  process.env.STATE_DIR = dir;
});

test('allows exactly 5 sends and blocks the 6th with retryAt = oldest + 24h', async () => {
  for (let i = 0; i < 5; i++) {
    const r = await reserve('u1', 'sms', new Date(T0.getTime() + i * H));
    assert.equal(r.allowed, true);
    assert.equal(r.retryAt, null);
    assert.equal(typeof r.reason, 'string');
  }
  const r = await reserve('u1', 'chat', new Date(T0.getTime() + 5 * H));
  assert.equal(r.allowed, false);
  assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H);
  assert.match(r.reason, /5 proactive messages/);
});

test('limit is shared across channels', async () => {
  const chans = ['sms', 'push', 'chat', 'sms', 'push'];
  for (const c of chans) assert.equal((await reserve('u2', c, T0)).allowed, true);
  const r = await reserve('u2', 'push', T0);
  assert.equal(r.allowed, false);
});

test('denied calls are not counted', async () => {
  for (let i = 0; i < 5; i++) await reserve('u3', 'sms', T0);
  for (let i = 0; i < 10; i++) {
    const r = await reserve('u3', 'sms', new Date(T0.getTime() + H));
    assert.equal(r.allowed, false);
    assert.equal(r.retryAt.getTime(), T0.getTime() + 24 * H);
  }
});

test('window slides: a send is free again exactly at its time + 24h', async () => {
  const times = [0, 1, 2, 3, 4].map((h) => new Date(T0.getTime() + h * H));
  for (const t of times) await reserve('u4', 'sms', t);
  const justBefore = new Date(T0.getTime() + 24 * H - 1);
  assert.equal((await reserve('u4', 'sms', justBefore)).allowed, false);
  const atExpiry = new Date(T0.getTime() + 24 * H);
  const r = await reserve('u4', 'sms', atExpiry);
  assert.equal(r.allowed, true);
  // Now window holds sends at 1h,2h,3h,4h (+ the new one at 24h): full again.
  const next = await reserve('u4', 'sms', new Date(T0.getTime() + 24 * H + 1));
  assert.equal(next.allowed, false);
  assert.equal(next.retryAt.getTime(), T0.getTime() + 1 * H + 24 * H);
});

test('retryAt is accurate: reserve at retryAt succeeds, one ms earlier fails', async () => {
  for (let i = 0; i < 5; i++) await reserve('u5', 'push', new Date(T0.getTime() + i * 2 * H));
  const blocked = await reserve('u5', 'push', new Date(T0.getTime() + 9 * H));
  assert.equal(blocked.allowed, false);
  const early = new Date(blocked.retryAt.getTime() - 1);
  assert.equal((await reserve('u5', 'push', early)).allowed, false);
  assert.equal((await reserve('u5', 'push', blocked.retryAt)).allowed, true);
});

test('customers are independent', async () => {
  for (let i = 0; i < 5; i++) await reserve('alice', 'sms', T0);
  assert.equal((await reserve('alice', 'sms', T0)).allowed, false);
  assert.equal((await reserve('bob', 'sms', T0)).allowed, true);
});

test('userIds with odd characters get separate state', async () => {
  for (let i = 0; i < 5; i++) await reserve('a/../b', 'sms', T0);
  assert.equal((await reserve('a/../b', 'sms', T0)).allowed, false);
  assert.equal((await reserve('a_b', 'sms', T0)).allowed, true);
});

test('state survives a fresh process', async () => {
  const script = `
    import { reserve } from ${JSON.stringify(BOT)};
    const r = await reserve('p1', 'chat', new Date(${T0.getTime()}));
    process.stdout.write(JSON.stringify(r));`;
  for (let i = 0; i < 5; i++) {
    const out = await run(script);
    assert.equal(JSON.parse(out).allowed, true);
  }
  const blocked = JSON.parse(await run(script));
  assert.equal(blocked.allowed, false);
  assert.equal(new Date(blocked.retryAt).getTime(), T0.getTime() + 24 * H);
});

test('concurrent calls in one process never exceed the limit', async () => {
  const results = await Promise.all(
    Array.from({ length: 40 }, (_, i) => reserve('burst', ['sms', 'push', 'chat'][i % 3], T0)),
  );
  assert.equal(results.filter((r) => r.allowed).length, 5);
});

test('concurrent processes never exceed the limit', async () => {
  const worker = `
    import { reserve } from ${JSON.stringify(BOT)};
    const at = new Date(${T0.getTime()});
    const out = [];
    for (let i = 0; i < 3; i++) out.push((await reserve('multi', 'sms', at)).allowed);
    process.stdout.write(JSON.stringify(out));`;
  const outs = await Promise.all(Array.from({ length: 12 }, () => run(worker)));
  const allowed = outs.flatMap((o) => JSON.parse(o)).filter(Boolean).length;
  assert.equal(allowed, 5);
  // No temp files or leftover locks.
  const leftovers = (await readdir(dir)).filter((f) => f.endsWith('.lock') || f.endsWith('.tmp'));
  assert.deepEqual(leftovers, []);
});

test('a stale lock left by a crashed process is broken', async () => {
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update('crashed').digest('hex');
  const lock = join(dir, `${key}.lock`);
  await mkdir(lock);
  const old = new Date(Date.now() - 60_000);
  await utimes(lock, old, old);
  const r = await reserve('crashed', 'sms', T0);
  assert.equal(r.allowed, true);
});

test('creates missing STATE_DIR including parents', async () => {
  process.env.STATE_DIR = join(dir, 'a', 'b', 'c');
  const r = await reserve('deep', 'sms', T0);
  assert.equal(r.allowed, true);
});

test('corrupt state file fails closed (throws, nothing sent)', async () => {
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update('bad').digest('hex');
  await writeFile(join(dir, `${key}.json`), '{not json');
  await assert.rejects(reserve('bad', 'sms', T0), /not valid JSON/);
});

test('invalid arguments throw', async () => {
  await assert.rejects(reserve('', 'sms', T0), TypeError);
  await assert.rejects(reserve('u', 'email', T0), TypeError);
  await assert.rejects(reserve('u', 'sms', '2026-10-23'), TypeError);
  await assert.rejects(reserve('u', 'sms', new Date('nope')), TypeError);
});

test('missing STATE_DIR throws', async () => {
  delete process.env.STATE_DIR;
  await assert.rejects(reserve('u', 'sms', T0), /STATE_DIR/);
});

function run(script) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', script], {
      env: process.env,
    });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => (out += d));
    child.stderr.on('data', (d) => (err += d));
    child.on('error', reject);
    child.on('close', (code) => (code === 0 ? resolve(out) : reject(new Error(err || `exit ${code}`))));
  });
}
